import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../src/types.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system: three followers in term 0, no vote', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout makes a candidate that sends RequestVote to the other two', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
});

test('timeout is refused for unknown ids and a second time', async () => {
  const h = await createHost();
  const r = await h.timeout('x');
  assert.equal(r.ok, false);
  await h.timeout('n0');
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.inFlight()).length, 2);
});

test('a node that voted in term 1 cannot time out', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const toN1 = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(toN1.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply, { id: reply.id, from: 'n1', to: 'n0', action: 'VoteReply', data: { term: 1, granted: true } });
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0' });
});

test('deliverAll with a single candidate elects it', async () => {
  const h = await createHost();
  await h.timeout('n2');
  await h.deliverAll();
  assert.equal((await h.node('n2'))!.role, 'leader');
  assert.deepEqual(await h.inFlight(), []);
});

test('candidates refuse each other', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  const rv = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n0')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply.data, { term: 1, granted: false });
  await h.deliver(reply.id);
  assert.equal((await h.node('n1'))!.role, 'candidate');
});

// Random interleavings of timeouts and deliveries (seeded), checking the safety rules after every step.
function rng(seed: number): () => number {
  return () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
}

async function checkSafety(h: Host): Promise<void> {
  const views = await Promise.all(NODES.map((n) => h.node(n)));
  const leaders = NODES.filter((_, i) => views[i]!.role === 'leader');
  assert.ok(leaders.length <= 1, 'at most one leader');
  for (const l of leaders) {
    const voters = NODES.filter((_, i) => views[i]!.votedFor === l);
    assert.ok(voters.length >= 2, 'leader holds a majority');
  }
}

test('all delivery orders are safe', async () => {
  const sets = [['n0'], ['n0', 'n1'], ['n0', 'n1', 'n2'], ['n2', 'n1']];
  let runs = 0;
  for (const timeouts of sets) {
    const stack: number[][] = [[]];
    while (stack.length) {
      const path = stack.pop()!;
      const h = await replay(timeouts, path);
      await checkSafety(h);
      const n = (await h.inFlight()).length;
      if (n === 0) runs++;
      for (let i = 0; i < n; i++) stack.push([...path, i]);
    }
  }
  assert.ok(runs > 10);
});

