// The brief's conclusion, as invariants over spec/election.cjs.
const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const leaders = (s) => NODES.filter((n) => s.role[n] === 'leader');

export const stateInvariants = [
  { name: 'at most one leader in term 1', pred: (s) => leaders(s).length <= 1 },
  {
    name: 'a leader holds the votes of a majority',
    pred: (s) => leaders(s).every((l) => NODES.filter((n) => s.term[n] === s.term[l] && s.votedFor[n] === l).length >= MAJORITY),
  },
  {
    name: 'every vote a candidate or leader counts was cast for it',
    pred: (s) => NODES.every((c) => s.votes[c].every((v) => s.votedFor[v] === c && s.term[v] === s.term[c])),
  },
  { name: 'terms stay in {0, 1}', pred: (s) => NODES.every((n) => s.term[n] === 0 || s.term[n] === 1) },
  {
    name: 'a node in term 0 is a follower without a vote',
    pred: (s) => NODES.every((n) => s.term[n] !== 0 || (s.role[n] === 'follower' && s.votedFor[n] === null)),
  },
  {
    name: 'a candidate or leader voted for itself',
    pred: (s) => NODES.every((n) => s.role[n] === 'follower' || s.votedFor[n] === n),
  },
];

export const transitionInvariants = [
  {
    name: 'no node votes twice in a term',
    pred: (pre, _a, _d, post) =>
      NODES.every((n) => pre.term[n] !== post.term[n] || pre.votedFor[n] === null || pre.votedFor[n] === post.votedFor[n]),
  },
  {
    name: 'a leader stays leader',
    pred: (pre, _a, _d, post) => NODES.every((n) => pre.role[n] !== 'leader' || post.role[n] === 'leader'),
  },
];

export default { stateInvariants, transitionInvariants };

