// Lockstep conformance: drive src/host.impl.ts and spec/election.cjs with the same random actions
// and compare the observable state (role, term, votedFor, messages in flight) after every step.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../src/types.ts';
// @ts-ignore: polygraph's loader is plain JS
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';

const NODES = ['n0', 'n1', 'n2'];
const spec = loadSpec(new URL('../spec/election.cjs', import.meta.url).pathname.replace(/^\/(\w:)/, '$1'));

const keyOf = (m: Message): string =>
  m.action === 'VoteReply' ? `VoteReply:${m.from}:${m.to}:${m.data.granted}` : `${m.action}:${m.from}:${m.to}`;

async function observe(h: Host) {
  const view = {
    role: {} as Record<string, string>,
    term: {} as Record<string, number>,
    votedFor: {} as Record<string, string | null>,
    leader: {} as Record<string, string | null>,
  };
  for (const n of NODES) {
    const v = (await h.node(n))!;
    view.role[n] = v.role;
    view.term[n] = v.term;
    view.votedFor[n] = v.votedFor;
    view.leader[n] = v.leader;
  }
  return { ...view, net: (await h.inFlight()).map(keyOf).sort() };
}

function rng(seed: number): () => number {
  return () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
}

test('implementation and spec agree step by step', async () => {
  for (let seed = 1; seed <= 300; seed++) {
    const r = rng(seed);
    const h = await createHost();
    spec.init();
    for (let step = 0; step < 30; step++) {
      const msgs = await h.inFlight();
      if (r() < 0.3 || msgs.length === 0) {
        const node = ['n0', 'n1', 'n2', 'x'][Math.floor(r() * 4)];
        const pre = JSON.stringify(spec.getState());
        const out = await h.timeout(node);
        spec.actions.TIMEOUT({ node });
        assert.equal(out.ok, JSON.stringify(spec.getState()) !== pre, `timeout(${node}) outcome`);
      } else {
        const m = msgs[Math.floor(r() * msgs.length)];
        await h.deliver(m.id);
        spec.actions.DELIVER({ msg: keyOf(m) });
      }
      const { votes, ...specView } = spec.getState();
      assert.deepEqual(await observe(h), specView, `seed ${seed} step ${step}`);
    }
  }
});

