});

// Random interleavings of timeouts and deliveries (seeded), checking the safety rules after every step.
function rng(seed: number): () => number {
  return () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
}

async function checkSafety(h: Host): Promise<void> {
  const views = await Promise.all(NODES.map((n) => h.node(n)));
  const leaders = NODES.filter((_, i) => views[i]!.role === 'leader');
  assert.ok(leaders.length <= 1, 'at most one leader');
  for (const l of leaders) {
    const voters = NODES.filter((_, i) => views[i]!.votedFor === l);
    assert.ok(voters.length >= 2, 'leader holds a majority');
  }
  for (const v of views) {
    if (v!.leader !== null) assert.deepEqual(leaders, [v!.leader], 'a known leader is the leader');
  }
}

test('random delivery orders are safe', async () => {
  for (let seed = 1; seed <= 500; seed++) {
    const r = rng(seed);
    const h = await createHost();
    const voted = new Map<string, string>();
    for (let step = 0; step < 40; step++) {
      const msgs = await h.inFlight();
      if (r() < 0.25 || msgs.length === 0) await h.timeout(NODES[Math.floor(r() * 3)]);
      else await h.deliver(msgs[Math.floor(r() * msgs.length)].id);
      await checkSafety(h);
      for (const n of NODES) {
        const v = (await h.node(n))!.votedFor;
        if (v !== null) {
          assert.ok(!voted.has(n) || voted.get(n) === v, 'no node votes twice');
          voted.set(n, v);
        }
      }
    }
  }
});

