import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../src/types.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system: three followers in term 0, no vote', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout makes a candidate that sends RequestVote to the other two', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
});

test('timeout is refused for unknown ids and a second time', async () => {
  const h = await createHost();
  const r = await h.timeout('x');
  assert.equal(r.ok, false);
  await h.timeout('n0');
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.inFlight()).length, 2);
});

test('a node that voted in term 1 cannot time out', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const toN1 = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(toN1.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.timeout('n1')).ok, false);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply, { id: reply.id, from: 'n1', to: 'n0', action: 'VoteReply', data: { term: 1, granted: true } });
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const announced = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(announced.map((m) => m.to).sort(), ['n1', 'n2']);
  for (const m of announced) {
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
});

test('deliverAll with a single candidate elects it and announces it', async () => {
  const h = await createHost();
  await h.timeout('n2');
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'leader', term: 1, votedFor: 'n2', leader: 'n2' });
  assert.deepEqual(await h.inFlight(), []);
  for (const n of ['n0', 'n1']) assert.deepEqual(await h.node(n), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n2' });
});

test('Leader moves a term-0 node to term 1 without a vote', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.deliver((await h.inFlight()).find((m) => m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  // n2 has not received n0's RequestVote yet; deliver the Leader announcement first.
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await h.timeout('n2')).ok, false);
});

test('Leader makes a candidate step down, keeping its vote for itself', async () => {
  const h = await createHost();
