'use strict';
// SAM v2 strict-profile spec of the stateful core of src/host.impl.ts:
// timeout(node), giveUp(node), and delivering one in-flight message (RequestVote / VoteReply / Leader).
// A message is a key "RequestVote:<from>:<to>", "VoteReply:<from>:<to>:<granted>" or "Leader:<from>:<to>";
// net is the sorted set of keys in flight (every message is sent at most once).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const INITIAL_STATE = {
  role: { n0: 'follower', n1: 'follower', n2: 'follower' },
  term: { n0: 0, n1: 0, n2: 0 },
  votedFor: { n0: null, n1: null, n2: null },
  leader: { n0: null, n1: null, n2: null },
  votes: { n0: [], n1: [], n2: [] },
  net: [],
};

const MESSAGES = [];
for (const a of NODES) for (const b of NODES) {
  if (a === b) continue;
  MESSAGES.push(`RequestVote:${a}:${b}`, `VoteReply:${a}:${b}:true`, `VoteReply:${a}:${b}:false`, `Leader:${a}:${b}`);
}

const withMsgs = (net, add, remove) => [...net.filter((k) => k !== remove), ...add].sort();

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      role: { type: 'object' },
      term: { type: 'object' },
      votedFor: { type: 'object' },
      leader: { type: 'object' },
      votes: { type: 'object' },
      net: { type: 'array' },
    },
    actions: {
      TIMEOUT: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string' } },
        domain: [{ node: 'n0' }, { node: 'n1' }, { node: 'n2' }, { node: 'x' }],
      },
      GIVE_UP: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string' } },
        domain: [{ node: 'n0' }, { node: 'n1' }, { node: 'n2' }, { node: 'x' }],
      },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: { type: 'string' } },
        domain: MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      TIMEOUT: (model) => (proposal, { reject, next, unchanged }) => {
        const n = proposal.node;
        if (!NODES.includes(n)) return reject('unknown-node');
        if (model.role[n] !== 'follower' || model.term[n] !== 0) return reject('cannot-start-election');
        next.role = { ...model.role, [n]: 'candidate' };
        next.term = { ...model.term, [n]: 1 };
        next.votedFor = { ...model.votedFor, [n]: n };
        next.votes = { ...model.votes, [n]: [n] };
        next.net = withMsgs(model.net, NODES.filter((o) => o !== n).map((o) => `RequestVote:${n}:${o}`), null);
        unchanged('leader');
      },
      GIVE_UP: (model) => (proposal, { reject, next, unchanged }) => {
        const n = proposal.node;
        if (!NODES.includes(n)) return reject('unknown-node');
        if (model.role[n] !== 'candidate') return reject('not-a-candidate');
        next.role = { ...model.role, [n]: 'follower' };
        next.votes = { ...model.votes, [n]: [] };
        unchanged('term', 'votedFor', 'leader', 'net');
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const key = proposal.msg;
        if (!model.net.includes(key)) return reject('not-in-flight');
        const [kind, from, to, g] = key.split(':');
        if (kind === 'RequestVote') {
          let granted;
          if (model.term[to] < 1) {
            granted = true;
            next.role = { ...model.role, [to]: 'follower' };
            next.term = { ...model.term, [to]: 1 };
            next.votedFor = { ...model.votedFor, [to]: from };
            next.votes = { ...model.votes, [to]: [] };
          } else {
            granted = model.role[to] === 'follower' && (model.votedFor[to] === null || model.votedFor[to] === from);
            if (granted) next.votedFor = { ...model.votedFor, [to]: from };
            else unchanged('votedFor');
            unchanged('role', 'term', 'votes');
          }
          next.net = withMsgs(model.net, [`VoteReply:${to}:${from}:${granted}`], key);
          unchanged('leader');
          return;
        }
        if (kind === 'Leader') {
          // Record the leader; a term-0 node joins term 1 without voting; a candidate steps down.
          next.net = withMsgs(model.net, [], key);
          if (model.role[to] === 'leader') {
            unchanged('role', 'term', 'votedFor', 'votes', 'leader');
            return;
          }
          next.role = { ...model.role, [to]: 'follower' };
          next.leader = { ...model.leader, [to]: from };
          if (model.term[to] < 1) {
            next.term = { ...model.term, [to]: 1 };
            next.votedFor = { ...model.votedFor, [to]: null };
            next.votes = { ...model.votes, [to]: [] };
          } else {
            unchanged('term', 'votedFor', 'votes');
          }
          return;
        }
        // VoteReply: counted only by a candidate in term 1 for a granted vote.
        if (model.role[to] === 'candidate' && model.term[to] === 1 && g === 'true') {
          const votes = [...new Set([...model.votes[to], from])].sort();
          next.votes = { ...model.votes, [to]: votes };
          if (votes.length >= MAJORITY) {
            next.role = { ...model.role, [to]: 'leader' };
            next.leader = { ...model.leader, [to]: to };
            next.net = withMsgs(model.net, NODES.filter((o) => o !== to).map((o) => `Leader:${to}:${o}`), key);
          } else {
            next.net = withMsgs(model.net, [], key);
            unchanged('role', 'leader');
          }
          unchanged('term', 'votedFor');
        } else {
          next.net = withMsgs(model.net, [], key);
          unchanged('role', 'term', 'votedFor', 'votes', 'leader');
        }
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  TIMEOUT: (data = {}) => intents.TIMEOUT(data),
  GIVE_UP: (data = {}) => intents.GIVE_UP(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

