// The brief's conclusion, as invariants over spec/election.cjs.
// `elected` is the spec's ghost history of nodes that ever became leader in term 1: since a leader can
// crash and recover as a follower, "at most one leader in a term" is stated over that history.
const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const leaders = (s) => NODES.filter((n) => s.role[n] === 'leader');
const isDeliver = (a, d, kind) => a === 'DELIVER' && d.msg.startsWith(kind + ':');

export const stateInvariants = [
  { name: 'at most one leader in term 1', pred: (s) => leaders(s).length <= 1 },
  { name: 'at most one node ever becomes leader in term 1', pred: (s) => s.elected.length <= 1 },
  { name: 'a current leader was elected', pred: (s) => leaders(s).every((l) => s.elected.includes(l)) },
  {
    name: 'every node ever elected holds the votes of a majority (votes survive crashes)',
    pred: (s) => s.elected.every((l) => NODES.filter((n) => s.term[n] === 1 && s.votedFor[n] === l).length >= MAJORITY),
  },
  {
    name: 'every vote a candidate or leader counts was cast for it',
    pred: (s) => NODES.every((c) => s.votes[c].every((v) => s.votedFor[v] === c && s.term[v] === s.term[c])),
  },
  { name: 'a down node counts no votes', pred: (s) => NODES.every((n) => s.role[n] !== 'down' || s.votes[n].length === 0) },
  { name: 'terms stay in {0, 1}', pred: (s) => NODES.every((n) => s.term[n] === 0 || s.term[n] === 1) },
  {
    name: 'a node in term 0 is a follower or down, without a vote or a known leader',
    pred: (s) =>
      NODES.every((n) => s.term[n] !== 0 || ((s.role[n] === 'follower' || s.role[n] === 'down') && s.votedFor[n] === null && s.leader[n] === null)),
  },
  {
    name: 'a candidate or leader voted for itself',
    pred: (s) => NODES.every((n) => (s.role[n] !== 'candidate' && s.role[n] !== 'leader') || s.votedFor[n] === n),
  },
  { name: 'a known leader was elected', pred: (s) => NODES.every((n) => s.leader[n] === null || s.elected.includes(s.leader[n])) },
  { name: 'a leader knows itself', pred: (s) => leaders(s).every((l) => s.leader[l] === l) },
  { name: 'a node knows itself as leader only if it was elected', pred: (s) => NODES.every((n) => s.leader[n] !== n || s.elected.includes(n)) },
  { name: 'a node that knows a leader is not a candidate', pred: (s) => NODES.every((n) => s.leader[n] === null || s.role[n] !== 'candidate') },
  {
    name: 'a Leader message never goes to a node that was elected',
    pred: (s) => s.net.every((k) => !k.startsWith('Leader:') || !s.elected.includes(k.split(':')[2])),
  },
