  },
  {
    name: 'crash and recover keep term, vote and known leader',
    pred: (pre, a, d, post) =>
      (a !== 'CRASH' && a !== 'RECOVER') || !NODES.includes(d.node) ||
      (pre.term[d.node] === post.term[d.node] && pre.votedFor[d.node] === post.votedFor[d.node] && pre.leader[d.node] === post.leader[d.node]),
  },
