    name: 'a message delivered to a down node changes nothing but the network',
    pred: (pre, a, d, post) =>
      a !== 'DELIVER' || pre.role[d.msg.split(':')[2]] !== 'down' ||
      ['role', 'term', 'votedFor', 'leader', 'votes', 'elected'].every((k) => JSON.stringify(pre[k]) === JSON.stringify(post[k])),
  },
  {
    name: 'a down node cannot time out',
    pred: (pre, a, d, post) => a !== 'TIMEOUT' || pre.role[d.node] !== 'down' || JSON.stringify(pre) === JSON.stringify(post),
  },
  {
    name: 'only a candidate becomes leader',
    pred: (pre, _a, _d, post) => NODES.every((n) => post.role[n] !== 'leader' || pre.role[n] === 'candidate' || pre.role[n] === 'leader'),
  },
