  await h.timeout('n1');
  // n1 reaches n2 first and is elected; n0 refuses n1, and n1's reply to n0 is ignored.
  await h.deliver((await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n2')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  // n2 refuses n0; the late (refused) reply and n0's refusal of n1 change nothing.
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n1' });
  assert.equal((await h.node('n1'))!.role, 'leader');
});

test('a granted reply that arrives after giveUp is ignored', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.deliver((await h.inFlight()).find((m) => m.to === 'n1')!.id);
  await h.giveUp('n0');
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.inFlight()).some((m) => m.action === 'Leader'), false);
});

test('candidates refuse each other', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  const rv = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n0')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply.data, { term: 1, granted: false });
  await h.deliver(reply.id);
  assert.equal((await h.node('n1'))!.role, 'candidate');
});

// Random interleavings of timeouts and deliveries (seeded), checking the safety rules after every step.
function rng(seed: number): () => number {
  return () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
}

/** `elected` accumulates every node seen as leader in the run: a leader may crash and recover as a follower. */
async function checkSafety(h: Host, elected: Set<string>): Promise<void> {
  const views = await Promise.all(NODES.map((n) => h.node(n)));
  for (let i = 0; i < 3; i++) if (views[i]!.role === 'leader') elected.add(NODES[i]);
  assert.ok(elected.size <= 1, 'at most one leader in the term');
  for (const l of elected) {
    const voters = NODES.filter((_, i) => views[i]!.votedFor === l);
    assert.ok(voters.length >= 2, 'leader holds a majority');
  }
  for (const v of views) {
    if (v!.leader !== null) assert.ok(elected.has(v!.leader), 'a known leader is the leader');
  }
}

test('random delivery orders are safe', async () => {
  for (let seed = 1; seed <= 500; seed++) {
    const r = rng(seed);
    const h = await createHost();
    const voted = new Map<string, string>();
    const elected = new Set<string>();
    for (let step = 0; step < 40; step++) {
      const msgs = await h.inFlight();
      const p = r();
      if (p < 0.25 || msgs.length === 0) await h.timeout(NODES[Math.floor(r() * 3)]);
      else if (p < 0.32) await h.giveUp(NODES[Math.floor(r() * 3)]);
      else if (p < 0.39) await h.crash(NODES[Math.floor(r() * 3)]);
      else if (p < 0.46) await h.recover(NODES[Math.floor(r() * 3)]);
      else await h.deliver(msgs[Math.floor(r() * msgs.length)].id);
      await checkSafety(h, elected);
      for (const n of NODES) {
        const v = (await h.node(n))!.votedFor;
        if (v !== null) {
          assert.ok(!voted.has(n) || voted.get(n) === v, 'no node votes twice');
          voted.set(n, v);
        }
      }
    }
  }
});
